"""Deduplicated mailbox source links and private converted document bytes."""

from alembic import op

revision = "0007_mail_intake"
down_revision = "0006_mailbox_connections"
branch_labels = None
depends_on = None

TABLES = ("mail_source_messages", "mail_source_attachments", "document_derivatives")


def upgrade() -> None:
    # The original autogenerated CHECK name was PostgreSQL-assigned; discover only that CHECK.
    op.execute("""
        DO $$ DECLARE c record; BEGIN
            FOR c IN SELECT conname FROM pg_constraint WHERE conrelid = 'resume_files'::regclass
                AND contype = 'c' AND pg_get_constraintdef(oid) LIKE '%mime_type%'
            LOOP EXECUTE format('ALTER TABLE resume_files DROP CONSTRAINT %I', c.conname); END LOOP;
        END $$;
        ALTER TABLE resume_files ADD CONSTRAINT resume_files_supported_mime CHECK(mime_type IN
            ('application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document',
             'application/msword'));
        CREATE TABLE mail_source_messages (
            id uuid PRIMARY KEY, created_at timestamptz NOT NULL,
            tenant_id uuid NOT NULL REFERENCES tenants(id), connection_id uuid NOT NULL,
            provider_message_id text NOT NULL, internet_message_id text,
            received_at timestamptz NOT NULL, generation integer NOT NULL CHECK(generation > 0),
            UNIQUE(tenant_id,id), UNIQUE(connection_id,provider_message_id),
            FOREIGN KEY(tenant_id,connection_id) REFERENCES mailbox_connections(tenant_id,id)
                ON DELETE CASCADE
        );
        CREATE INDEX ix_mail_message_retention ON mail_source_messages(tenant_id,received_at);
        CREATE TABLE mail_source_attachments (
            id uuid PRIMARY KEY, created_at timestamptz NOT NULL,
            tenant_id uuid NOT NULL REFERENCES tenants(id), message_id uuid NOT NULL,
            provider_attachment_id text NOT NULL, filename text NOT NULL, mime_type text NOT NULL,
            byte_length integer NOT NULL CHECK(byte_length >= 0), upload_id uuid,
            status text NOT NULL CHECK(status IN
            ('queued','processing','retry_wait','completed','needs_review')),
            failure_code text, UNIQUE(tenant_id,id), UNIQUE(message_id,provider_attachment_id),
            FOREIGN KEY(tenant_id,message_id) REFERENCES mail_source_messages(tenant_id,id)
                ON DELETE CASCADE,
            FOREIGN KEY(tenant_id,upload_id) REFERENCES cv_uploads(tenant_id,id) ON DELETE CASCADE
        );
        CREATE TABLE document_derivatives (
            id uuid PRIMARY KEY, created_at timestamptz NOT NULL,
            tenant_id uuid NOT NULL REFERENCES tenants(id), upload_id uuid NOT NULL UNIQUE,
            content bytea NOT NULL CHECK(octet_length(content) BETWEEN 1 AND 20971520),
            sha256 text NOT NULL, converter_version text NOT NULL,
            FOREIGN KEY(tenant_id,upload_id) REFERENCES cv_uploads(tenant_id,id) ON DELETE CASCADE
        );
        GRANT INSERT ON resume_files, cv_uploads TO recruitment_worker;
    """)
    for table in TABLES:
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        op.execute(f"ALTER TABLE {table} FORCE ROW LEVEL SECURITY")
        op.execute(f"""CREATE POLICY api_isolation ON {table} TO recruitment_api
            USING (tenant_id = tenant_context() AND tenant_is_member(tenant_id))
            WITH CHECK (tenant_id = tenant_context() AND tenant_is_member(tenant_id))""")
        op.execute(f"""CREATE POLICY worker_isolation ON {table} TO recruitment_worker
            USING (tenant_id = tenant_context()) WITH CHECK (tenant_id = tenant_context())""")
        op.execute(f"GRANT SELECT ON {table} TO recruitment_api")
        op.execute(f"GRANT SELECT, INSERT, UPDATE, DELETE ON {table} TO recruitment_worker")


def downgrade() -> None:
    # Refuse to invalidate stored DOC originals; an operator must export/delete them first.
    op.execute("""
        DO $$ BEGIN IF EXISTS(SELECT 1 FROM mail_source_messages)
            OR EXISTS(SELECT 1 FROM document_derivatives) THEN
            RAISE EXCEPTION 'Export or retain mailbox intake and derivatives before downgrade';
        END IF; END $$;
        DO $$ BEGIN IF EXISTS(SELECT 1 FROM resume_files
            WHERE mime_type = 'application/msword') THEN
            RAISE EXCEPTION 'Cannot downgrade while legacy DOC files exist'; END IF; END $$;
        ALTER TABLE resume_files DROP CONSTRAINT resume_files_supported_mime;
        ALTER TABLE resume_files ADD CONSTRAINT resume_files_mime_type_check CHECK(mime_type IN
            ('application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document'));
        REVOKE INSERT ON resume_files FROM recruitment_worker;
    """)
    for table in reversed(TABLES):
        op.execute(f"DROP TABLE {table}")
